"use client";
import { useEffect, useRef, type CSSProperties, type ReactNode } from "react";
import { AnimatePresence, motion } from "motion/react";
import {
  SectionImage,
  sectionStyles,
  useSectionEnvironment,
  useSectionSelection,
} from "./section-shared";
export interface WipeSliderItem {
  id: string;
  title: string;
  description?: string;
  src?: string;
  alt?: string;
  content?: ReactNode;
}
export interface WipeSliderProps {
  items: readonly WipeSliderItem[];
  index?: number;
  defaultIndex?: number;
  onChange?: (index: number) => void;
  onSelect?: (item: WipeSliderItem, index: number) => void;
  duration?: number;
  dim?: number;
  height?: number;
  className?: string;
  style?: CSSProperties;
  label?: string;
}
/** Directional full-frame wipe, masked copy, and rolling percentage index. */
export function WipeSlider({
  items,
  index,
  defaultIndex = 0,
  onChange,
  onSelect,
  duration = 0.9,
  dim = 0.2,
  height = 720,
  className = "",
  style,
  label = "Wipe slider",
}: WipeSliderProps) {
  const env = useSectionEnvironment(),
    selection = useSectionSelection(
      items.length,
      index,
      defaultIndex,
      onChange,
    ),
    direction = useRef(1),
    previous = useRef(selection.selected),
    touch = useRef<number | null>(null);
  useEffect(() => {
    previous.current = selection.selected;
  }, [selection.selected]);
  const selected = selection.selected,
    item = items[selected],
    t = {
      duration: env.reduced ? 0 : Math.max(0, duration),
      ease: [0.76, 0, 0.24, 1] as const,
    };
  const next = (delta: number) => {
    direction.current = Math.sign(delta);
    selection.select(selection.current.current + delta);
  };
  return (
    <div
      ref={env.ref}
      role="region"
      aria-roledescription="carousel"
      aria-label={label}
      tabIndex={0}
      className={`z-as z-as-wipe ${className}`}
      data-section="wipe-slider"
      data-index={selected}
      data-direction={direction.current}
      style={{ height: `min(${height}px,100svh)`, minHeight: 440, ...style }}
      onKeyDown={(e) => {
        if (e.key === "ArrowRight" || e.key === "ArrowLeft") {
          e.preventDefault();
          next(e.key === "ArrowRight" ? 1 : -1);
        }
      }}
      onPointerDown={(e) => {
        if (!(e.target as HTMLElement).closest("button,a"))
          touch.current = e.clientX;
      }}
      onPointerUp={(e) => {
        if (touch.current !== null && Math.abs(e.clientX - touch.current) > 45)
          next(e.clientX < touch.current ? 1 : -1);
        touch.current = null;
      }}
      onPointerCancel={() => {
        touch.current = null;
      }}
    >
      <style>
        {sectionStyles +
          `.z-as-wipe{overflow:hidden;color:#fff;touch-action:pan-y;background:#181818}.z-as-wipe .z-as-wipe-layer{position:absolute;inset:0}.z-as-wipe .z-as-wipe-title{position:absolute;top:32px;left:3.2%;right:3.2%;font-size:clamp(54px,10vw,138px);font-weight:400;line-height:1.08;letter-spacing:-.05em}.z-as-wipe .z-as-wipe-info{position:absolute;top:47%;left:3.2%;right:3.2%;display:grid;grid-template-columns:1fr 1fr 80px;gap:24px}.z-as-wipe .z-as-wipe-info p{max-width:350px}.z-as-wipe .z-as-controls{position:absolute;bottom:65px;left:0;right:0}.z-as-wipe .z-as-wipe-track{position:absolute;bottom:24px;left:3.2%;right:3.2%;display:flex;gap:18px}.z-as-wipe .z-as-wipe-track button{height:20px;background:none;flex:1;padding:0;border-top:2px solid #fff4}.z-as-wipe .z-as-wipe-track button[aria-current=true]{border-color:white}@media(max-width:600px){.z-as-wipe .z-as-wipe-info{top:auto;bottom:150px;grid-template-columns:1fr 70px}.z-as-wipe .z-as-wipe-info>small{grid-column:1/-1}.z-as-wipe .z-as-wipe-title{top:25px}.z-as-wipe .z-as-wipe-info p{font-size:13px}}`}
      </style>
      <AnimatePresence initial={false} custom={direction.current}>
        {item && (
          <motion.div
            key={item.id}
            className="z-as-wipe-layer"
            initial={{
              clipPath:
                direction.current > 0
                  ? "inset(0 0 0 100%)"
                  : "inset(0 100% 0 0)",
            }}
            animate={{ clipPath: "inset(0 0 0 0)" }}
            exit={{ opacity: 1 }}
            transition={t}
            style={{ zIndex: 2 }}
          >
            <SectionImage item={item} className="z-as-fill" />
            <div
              className="z-as-fill"
              style={{ background: `rgba(0,0,0,${dim})` }}
            />
          </motion.div>
        )}
      </AnimatePresence>
      <div
        style={{
          position: "absolute",
          inset: 0,
          zIndex: 4,
          pointerEvents: "none",
        }}
      >
        <h2 className="z-as-wipe-title z-as-mask">
          <AnimatePresence mode="popLayout" initial={false}>
            <motion.span
              key={item?.id}
              style={{ display: "block" }}
              initial={{ y: direction.current * 110 + "%" }}
              animate={{ y: 0 }}
              exit={{ y: direction.current * -110 + "%" }}
              transition={t}
            >
              {item?.title}
            </motion.span>
          </AnimatePresence>
        </h2>
        <div className="z-as-wipe-info">
          <small>Chapter {String(selected + 1).padStart(2, "0")}</small>
          <div className="z-as-mask">
            <AnimatePresence mode="popLayout" initial={false}>
              <motion.p
                key={item?.id}
                initial={{ y: "110%" }}
                animate={{ y: 0 }}
                exit={{ y: "-110%" }}
                transition={{ ...t, delay: env.reduced ? 0 : 0.06 }}
              >
                {item?.description}
              </motion.p>
            </AnimatePresence>
          </div>
          <div className="z-as-mask" style={{ height: 24, textAlign: "right" }}>
            <motion.div animate={{ y: -selected * 24 }} transition={t}>
              {items.map((_, i) => (
                <div key={i} style={{ height: 24 }}>
                  {String(Math.round(((i + 1) / items.length) * 100)).padStart(
                    3,
                    "0",
                  )}
                  %
                </div>
              ))}
            </motion.div>
          </div>
        </div>
      </div>
      <nav
        className="z-as-controls"
        style={{ zIndex: 5 }}
        aria-label="Slide navigation"
      >
        <div className="z-as-pill">
          <button
            type="button"
            aria-label="Previous slide"
            onClick={() => next(-1)}
          >
            ‹
          </button>
          <span aria-live="polite">{item?.title ?? "No slides"}</span>
          <button type="button" aria-label="Next slide" onClick={() => next(1)}>
            ›
          </button>
        </div>
      </nav>
      <div className="z-as-wipe-track" style={{ zIndex: 5 }}>
        {items.map((entry, i) => (
          <button
            key={entry.id}
            type="button"
            aria-label={`Go to slide ${i + 1}`}
            aria-current={selected === i}
            onClick={() => {
              direction.current = i >= selected ? 1 : -1;
              selection.select(i);
              onSelect?.(entry, i);
            }}
          />
        ))}
      </div>
    </div>
  );
}
